// How many times each type appears in a list of types. The file's other
// by-type reading, alikeItemGroupsIn, collects the items themselves because the
// premium side prices them; here only the tally matters.
const countByType = (types: string[]): Map<string, number> =>
  types.reduce(
    (counts, type) => counts.set(type, (counts.get(type) ?? 0) + 1),
    new Map<string, number>(),
  );

const typesOfInsuredItems = (policy: Policy): string[] =>
  policy.items.map((item) => item.type);

const typesOfDamagedItems = (incident: Incident): string[] =>
  incident.damages.map((damage) => damage.itemType);

// A damage entry stands for one damaged item, so an incident cannot name more
// damages of a type than the policy insures of that type. Asking for the
// overclaimed type — rather than testing each damage in turn — puts this beside
// the file's other three misses: a lookup that yields nothing when all is well
// and names the offender when it is not.
const overclaimedTypeIn = (incident: Incident, policy: Policy): string | undefined => {
  const insuredCounts = countByType(typesOfInsuredItems(policy));
  return [...countByType(typesOfDamagedItems(incident))]
    .filter(([type, damaged]) => damaged > (insuredCounts.get(type) ?? 0))
    .map(([type]) => type)
    .at(0);
};

// The whole claim is rejected rather than settled in part, so the overclaim is
// checked before any damage is priced.
const rejectOverclaimedTypes = (incident: Incident, policy: Policy): void => {
  const overclaimed = overclaimedTypeIn(incident, policy);
  if (overclaimed !== undefined) {
    throw new Error(
      `the policy does not cover that many items of type "${overclaimed}"`,
    );
  }
};

// One incident can damage several items; each damage is settled on its own
// (and so bears its own deductible), and the incident pays out their sum.
const payoutForIncident = (incident: Incident, policy: Policy): number => {
  rejectOverclaimedTypes(incident, policy);
  return incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage, policy),
    0,
  );
};

